import React, { useState, useEffect, useRef } from "react";
import "./CrosswordGame.css";

const CrosswordGame = ({
  question,
  onAnswerSubmit,
  timer,
  answerSubmitted,
  showFeedback,
  isCorrectAnswer,
}) => {
  const [selectedCells, setSelectedCells] = useState([]);
  const [isSelecting, setIsSelecting] = useState(false);
  const [selectionDirection, setSelectionDirection] = useState(null);
  const [correctWords, setCorrectWords] = useState([]);
  const [wrongCells, setWrongCells] = useState([]);
  const [timeoutCells, setTimeoutCells] = useState([]);
  const [foundWords, setFoundWords] = useState([]);
  const [attempts, setAttempts] = useState(0);
  const gridRef = useRef(null);

  // Safe access to question properties
  const grid = question?.grid || [];
  const words = question?.words || { across: [], down: [] };
  const clue = question?.clue || "Solve the crossword puzzle";

  // Get all valid words from the crossword
  const allValidWords = React.useMemo(() => {
    const acrossWords = Array.isArray(words.across) ? words.across : [];
    const downWords = Array.isArray(words.down) ? words.down : [];

    return [
      ...acrossWords.map((w) =>
        (typeof w === "string" ? w : w?.word || "").toUpperCase()
      ),
      ...downWords.map((w) =>
        (typeof w === "string" ? w : w?.word || "").toUpperCase()
      ),
    ].filter((word) => word.length > 0);
  }, [words]);

  useEffect(() => {
    if (!answerSubmitted) {
      setSelectedCells([]);
      setCorrectWords([]);
      setWrongCells([]);
      setTimeoutCells([]);
      setFoundWords([]);
      setAttempts(0);
    }
  }, [question, answerSubmitted]);

  // Handle timeout - fill with grey and submit final score
  useEffect(() => {
    if (timer === 0 && !answerSubmitted) {
      const allCells = [];
      grid.forEach((row, rowIndex) => {
        row.forEach((cell, colIndex) => {
          if (cell && cell !== " ") {
            allCells.push(`${rowIndex}-${colIndex}`);
          }
        });
      });
      setTimeoutCells(allCells);

      // Auto-submit when time runs out with current progress
      setTimeout(() => {
        const scoreData = {
          foundWords: foundWords.length,
          totalWords: allValidWords.length,
          attempts: attempts,
          timeTaken: 60, // 60 seconds total
        };
        onAnswerSubmit(scoreData);
      }, 1000);
    }
  }, [
    timer,
    answerSubmitted,
    grid,
    foundWords,
    attempts,
    onAnswerSubmit,
    allValidWords,
  ]);

  // Clear wrong cells after 1 second
  useEffect(() => {
    if (wrongCells.length > 0) {
      const timer = setTimeout(() => {
        setWrongCells([]);
        setSelectedCells([]);
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [wrongCells]);

  // Check if all words are found and auto-submit
  useEffect(() => {
    if (
      foundWords.length === allValidWords.length &&
      allValidWords.length > 0 &&
      !answerSubmitted
    ) {
      const scoreData = {
        foundWords: foundWords.length,
        totalWords: allValidWords.length,
        attempts: attempts,
        timeTaken: 60 - timer, // Time taken to complete
      };
      setTimeout(() => {
        onAnswerSubmit(scoreData);
      }, 500);
    }
  }, [
    foundWords,
    allValidWords,
    answerSubmitted,
    attempts,
    timer,
    onAnswerSubmit,
  ]);

  const getCellClass = (row, col) => {
    const cellId = `${row}-${col}`;
    let className = "crossword-cell";

    // Check if cell exists and is not empty
    if (!grid[row] || !grid[row][col] || grid[row][col] === " ") {
      return `${className} empty`;
    }

    if (correctWords.includes(cellId)) {
      className += " correct";
    } else if (wrongCells.includes(cellId)) {
      className += " wrong";
    } else if (timeoutCells.includes(cellId)) {
      className += " timeout";
    } else if (selectedCells.includes(cellId)) {
      className += " selecting";
    }

    return className;
  };

  const getWordFromSelection = (cells) => {
    if (cells.length === 0) return "";

    // Sort cells to maintain order
    const sortedCells = [...cells].sort((a, b) => {
      const [rowA, colA] = a.split("-").map(Number);
      const [rowB, colB] = b.split("-").map(Number);

      if (selectionDirection === "across") {
        return colA - colB;
      } else {
        return rowA - rowB;
      }
    });

    return sortedCells
      .map((cell) => {
        const [row, col] = cell.split("-").map(Number);
        return grid[row]?.[col] || "";
      })
      .join("");
  };

  const handleCellMouseDown = (row, col) => {
    if (answerSubmitted || !grid[row]?.[col] || grid[row][col] === " ") return;

    setIsSelecting(true);
    setSelectedCells([`${row}-${col}`]);
    setSelectionDirection(null);
  };

  const handleCellMouseEnter = (row, col) => {
    if (!isSelecting || !grid[row]?.[col] || grid[row][col] === " ") return;

    const currentCell = `${row}-${col}`;

    if (selectedCells.length === 1) {
      // Determine direction based on first and current cell
      const [firstRow, firstCol] = selectedCells[0].split("-").map(Number);

      if (row === firstRow && Math.abs(col - firstCol) > 0) {
        setSelectionDirection("across");
      } else if (col === firstCol && Math.abs(row - firstRow) > 0) {
        setSelectionDirection("down");
      } else {
        return; // Diagonal selection not allowed
      }
    }

    if (selectionDirection) {
      const newSelectedCells = getCellsInLine(selectedCells[0], currentCell);
      setSelectedCells(newSelectedCells);
    } else if (!selectedCells.includes(currentCell)) {
      setSelectedCells([currentCell]);
    }
  };

  const handleCellMouseUp = () => {
    if (!isSelecting) return;

    setIsSelecting(false);

    if (selectedCells.length > 0) {
      const selectedWord = getWordFromSelection(selectedCells);

      // Increment attempts counter
      setAttempts((prev) => prev + 1);

      // Check if selected word matches any valid word
      if (
        allValidWords.includes(selectedWord.toUpperCase()) &&
        !foundWords.includes(selectedWord.toUpperCase())
      ) {
        // Mark as correct and add to found words
        setCorrectWords((prev) => [...prev, ...selectedCells]);
        setFoundWords((prev) => [...prev, selectedWord.toUpperCase()]);
        setSelectedCells([]);
      } else {
        // Mark as wrong temporarily
        setWrongCells([...selectedCells]);
      }
    }
  };

  const getCellsInLine = (startCell, endCell) => {
    const [startRow, startCol] = startCell.split("-").map(Number);
    const [endRow, endCol] = endCell.split("-").map(Number);

    const cells = [];

    if (selectionDirection === "across") {
      const minCol = Math.min(startCol, endCol);
      const maxCol = Math.max(startCol, endCol);
      for (let col = minCol; col <= maxCol; col++) {
        if (grid[startRow]?.[col] && grid[startRow][col] !== " ") {
          cells.push(`${startRow}-${col}`);
        }
      }
    } else if (selectionDirection === "down") {
      const minRow = Math.min(startRow, endRow);
      const maxRow = Math.max(startRow, endRow);
      for (let row = minRow; row <= maxRow; row++) {
        if (grid[row]?.[startCol] && grid[row][startCol] !== " ") {
          cells.push(`${row}-${startCol}`);
        }
      }
    }

    return cells;
  };

  // Render nothing if no grid data
  if (!grid || grid.length === 0) {
    return (
      <div className="crossword-question">
        <h2>Crossword Puzzle</h2>
        <p>No crossword data available.</p>
      </div>
    );
  }

  return (
    <div className="crossword-question">
      <h2>Crossword Puzzle</h2>
      <p className="crossword-clue">{clue}</p>

      <div className="crossword-stats">
        <div className="stat">
          <strong>Words Found:</strong> {foundWords.length}/
          {allValidWords.length}
        </div>
        <div className="stat">
          <strong>Attempts:</strong> {attempts}
        </div>
        <div className="stat">
          <strong>Time Left:</strong> {timer}s
        </div>
      </div>

      <div
        className="crossword-grid"
        ref={gridRef}
        onMouseLeave={() => setIsSelecting(false)}
        onMouseUp={handleCellMouseUp}
      >
        {grid.map((row, rowIndex) => (
          <div key={rowIndex} className="crossword-row">
            {row.map((cell, cellIndex) => (
              <div
                key={cellIndex}
                className={getCellClass(rowIndex, cellIndex)}
                onMouseDown={() => handleCellMouseDown(rowIndex, cellIndex)}
                onMouseEnter={() => handleCellMouseEnter(rowIndex, cellIndex)}
                onMouseUp={handleCellMouseUp}
              >
                {cell && cell !== " " ? cell : ""}
              </div>
            ))}
          </div>
        ))}
      </div>

      <div className="crossword-instructions">
        <p>
          💡 <strong>How to play:</strong> Click and drag to select words
          horizontally or vertically
        </p>
        <p>✅ Correct words will turn green automatically</p>
        <p>❌ Wrong selections will flash red for 1 second</p>
        <p>⏰ Game auto-submits when all words are found or time runs out</p>
        <p>
          📊 <strong>Progress:</strong> {foundWords.length} of{" "}
          {allValidWords.length} words found
        </p>
      </div>

      {foundWords.length > 0 && (
        <div className="found-words">
          <h3>Words Found:</h3>
          <div className="words-list">
            {foundWords.map((word, index) => (
              <span key={index} className="found-word">
                {word}
              </span>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default CrosswordGame;
